import clsx from 'clsx';
import React, { ComponentPropsWithRef } from 'react';
import type {
  TTailwindBgClass,
  TTailwindContentClass,
  TTailwindRadiusClass,
  TTailwindSizeClass,
  TTailwindTextLabelClass
} from '@rbx/foundation-tailwind/classes';

export const statusIndicatorVariants = ['Dot', 'Numeric'] as const;
export type TStatusIndicatorVariant = (typeof statusIndicatorVariants)[number];

export const statusIndicatorColors = [
  'Success',
  'Warning',
  'Alert',
  'Emphasis',
  'Neutral',
  'Standard',
  'Voice'
] as const;
export type TStatusIndicatorColor = (typeof statusIndicatorColors)[number];

export const statusIndicatorNumericColors = ['Emphasis', 'Standard'] as const;
export type TStatusIndicatorNumericColor = (typeof statusIndicatorNumericColors)[number];

export const statusIndicatorSizes = ['XSmall', 'Small', 'Medium', 'Large', 'XLarge'] as const;
export type TStatusIndicatorSize = (typeof statusIndicatorSizes)[number];

export const statusIndicatorNumericSizes = ['Medium', 'Large'] as const;
export type TStatusIndicatorNumericSize = (typeof statusIndicatorNumericSizes)[number];

export const statusIndicatorShapes = ['Circle', 'Ring', 'Square'] as const;
export type TStatusIndicatorShape = (typeof statusIndicatorShapes)[number];

type TStatusIndicatorBaseProps = Omit<ComponentPropsWithRef<'div'>, 'children' | 'color'>;

export type TStatusIndicatorProps =
  | (TStatusIndicatorBaseProps & {
      /** The indicator style. @default 'Dot' */
      variant?: 'Dot';
      /** The color variant. @default 'Emphasis' */
      color?: TStatusIndicatorColor;
      /** The dot size. @default 'Medium' */
      size?: TStatusIndicatorSize;
      /** The indicator shape. @default 'Circle' */
      shape?: TStatusIndicatorShape;
      /** The mask color (CSS outline-color). */
      mask?: string;
      value?: never;
    })
  | (TStatusIndicatorBaseProps & {
      /** The indicator style. @default 'Dot' */
      variant: 'Numeric';
      /** The color variant. @default 'Emphasis' */
      color?: TStatusIndicatorNumericColor;
      /** The dot size. @default 'Medium' */
      size?: TStatusIndicatorNumericSize;
      shape?: never;
      mask?: never;
      /** The number to display (e.g. an unread count). */
      value: string;
    });

const bgClasses: Record<TStatusIndicatorColor, TTailwindBgClass | `bg-[var(${string})]`> = {
  Success: 'bg-system-success',
  Warning: 'bg-system-warning',
  Alert: 'bg-system-alert',
  Emphasis: 'bg-system-emphasis',
  Neutral: 'bg-system-neutral',
  Standard: 'bg-action-standard',
  Voice: 'bg-[var(--color-extended-orange-600)]'
};

const contentClasses: Record<
  TStatusIndicatorColor,
  TTailwindContentClass | `content-[var(${string})]`
> = {
  Success: 'content-system-success',
  Warning: 'content-system-warning',
  Alert: 'content-system-alert',
  Emphasis: 'content-system-emphasis',
  Neutral: 'content-system-neutral',
  Standard: 'content-[var(--color-action-standard-background)]',
  Voice: 'content-[var(--color-extended-orange-600)]'
};

const numericColorClasses: Record<
  TStatusIndicatorNumericColor,
  TTailwindContentClass | `content-[var(${string})]`
> = {
  Emphasis: 'content-[var(--dark-mode-content-emphasis)]',
  Standard: 'content-emphasis'
};

const sizeClasses: Record<TStatusIndicatorSize, TTailwindSizeClass> = {
  XSmall: 'size-100',
  Small: 'size-150',
  Medium: 'size-200',
  Large: 'size-250',
  XLarge: 'size-300'
};

const numericClasses: Record<
  TStatusIndicatorNumericSize,
  `min-width-${string} height-${number} ${TTailwindTextLabelClass}`
> = {
  Medium: 'min-width-400 height-400 text-label-small',
  Large: 'min-width-500 height-500 text-label-medium'
};

const shapeClasses: Record<Exclude<TStatusIndicatorShape, 'Ring'>, TTailwindRadiusClass> = {
  Circle: 'radius-circle',
  Square: 'radius-none'
};

/**
 * A status indicator marks unread messages, notifications, active items, or a user's availability.
 *
 * - The `Dot` variant renders a filled circle, ring, or square.
 * - The `Numeric` variant renders a count inside a pill.
 */
export const StatusIndicator = React.forwardRef<HTMLDivElement, TStatusIndicatorProps>(
  (props, ref) => {
    if (props.variant === 'Numeric') {
      const { variant: _, color = 'Emphasis', size = 'Medium', value, className, ...rest } = props;
      return (
        <div
          ref={ref}
          {...rest}
          className={clsx(
            'foundation-web-status-indicator inline-flex justify-center items-center radius-circle',
            numericClasses[size],
            bgClasses[color],
            numericColorClasses[color],
            className
          )}>
          <span className='padding-x-xsmall'>{value}</span>
        </div>
      );
    }

    const {
      variant: _,
      color = 'Emphasis',
      size = 'Medium',
      shape = 'Circle',
      mask,
      value,
      className,
      style,
      ...rest
    } = props;

    const maskClass = mask ? '[outline:solid_3px]' : undefined;

    if (shape === 'Ring') {
      return (
        <div
          ref={ref}
          {...rest}
          className={clsx(
            'foundation-web-status-indicator flex justify-center items-center radius-circle',
            sizeClasses[size],
            contentClasses[color],
            maskClass,
            className
          )}
          style={mask ? { ...style, backgroundColor: mask, outlineColor: mask } : style}>
          <svg viewBox='0 0 20 20' className='size-full'>
            <path
              d='M10 20C15.5228 20 20 15.5228 20 10C20 4.47715 15.5228 0 10 0C4.47715 0 0 4.47715 0 10C0 15.5228 4.47715 20 10 20ZM10 15C12.7614 15 15 12.7614 15 10C15 7.23858 12.7614 5 10 5C7.23858 5 5 7.23858 5 10C5 12.7614 7.23858 15 10 15Z'
              fillRule='evenodd'
              clipRule='evenodd'
              fill='currentColor'
            />
          </svg>
        </div>
      );
    }

    return (
      <div
        ref={ref}
        {...rest}
        className={clsx(
          'foundation-web-status-indicator',
          sizeClasses[size],
          bgClasses[color],
          shapeClasses[shape],
          maskClass,
          className
        )}
        style={mask ? { ...style, outlineColor: mask } : style}
      />
    );
  }
);

StatusIndicator.displayName = 'StatusIndicator';
